import SwiftUI

struct AgentsView:View{
 @EnvironmentObject var work:Workspace;@State private var rewindTurn=1;@State private var showEvents=false
 var running:Bool{["starting","running"].contains(work.sessionInfo["status"] as? String ?? "")}
 var body:some View{HSplitView{VStack(alignment:.leading,spacing:10){HStack{Text("Scoped sessions").font(.headline);Spacer();Button("New"){work.selectedSession="";work.messages=[];work.events=[];work.sessionInfo=[:];work.suggestions=[]}};List(selection:$work.selectedSession){ForEach(work.sessions,id:\.recordId){session in VStack(alignment:.leading,spacing:4){Text("\(session["kind"] ?? "task") · \(session["provider"] ?? "agent")").font(.headline);Text(session["status"] as? String ?? "unknown").font(.caption).foregroundStyle(.secondary);Text(String(session.recordId.prefix(12))).font(.caption.monospaced())}.tag(session.recordId)}};Text("Each new task starts with its own CLI context. Field help never inherits this chat.").font(.caption).foregroundStyle(.secondary)}.frame(minWidth:210,maxWidth:270)
 VStack(alignment:.leading,spacing:12){HStack{Picker("Agent",selection:$work.provider){ForEach(work.providers,id:\.providerId){p in Text("\(p["id"] ?? "agent")\((p["available"] as? Bool)==false ? " · unavailable":"")").tag(p["id"] as? String ?? "")}};if !work.sessionInfo.isEmpty{FieldView(field:Field("session.status","Session",work.sessionInfo["status"] ?? "unknown",meaning:"CLI turn state, independent of source collector and processing state."))};Toggle("Events",isOn:$showEvents).toggleStyle(.button)}
 if work.selectedSession.isEmpty{Text("Describe what data to collect, where it should come from, and where to save it. The agent works in its dedicated workspace. Review its instructions before starting; source archives stay read-only.").foregroundStyle(.secondary)}else{SessionStats().environmentObject(work)}
 ScrollViewReader{proxy in ScrollView{LazyVStack(alignment:.leading,spacing:14){ForEach(Array(work.messages.enumerated()),id:\.offset){index,message in VStack(alignment:.leading,spacing:5){Text((message["role"] as? String ?? "event").capitalized).font(.caption.bold()).foregroundStyle(.secondary);Text(message["text"] as? String ?? "").textSelection(.enabled).frame(maxWidth:.infinity,alignment:.leading)}.padding(12).background(.quaternary,in:RoundedRectangle(cornerRadius:10)).id(index)};if showEvents{Text(Workspace.pretty(work.events)).font(.system(.caption,design:.monospaced)).textSelection(.enabled)};Color.clear.frame(height:1).id("bottom")}}.onChange(of:work.messages.count){_,_ in proxy.scrollTo("bottom",anchor:.bottom)}}
 if !work.selectedSession.isEmpty{HStack{Button("Stop"){Task{_ = await work.request("session-stop",["id":work.selectedSession]);await work.pollSession()}}.disabled(!running);Menu("Context"){Button("Reset into fresh session"){operate("session-reset")};Button("Fork this session"){operate("session-branch")};Button("Compact into fresh session"){operate("session-compact")}}.disabled(running);Stepper("Turn \(rewindTurn)",value:$rewindTurn,in:1...max(1,(work.sessionInfo["turn"] as? Int ?? 1)));Button("Branch from turn"){operate("session-rewind",extra:["turn":rewindTurn])}.disabled(running)}}
 if !work.suggestions.isEmpty{HStack{ForEach(work.suggestions,id:\.self){prompt in Button(prompt){work.sessionPrompt=prompt}.font(.caption)}}}
 TextEditor(text:$work.sessionPrompt).font(.body).frame(minHeight:75,maxHeight:130).overlay(RoundedRectangle(cornerRadius:8).stroke(.quaternary));HStack{Text("Runs the selected local CLI. Its configured model service receives your submitted prompt and chosen context.").font(.caption).foregroundStyle(.secondary);Spacer();Button(work.selectedSession.isEmpty ? "Start collection session":"Send",systemImage:"arrow.up.circle.fill"){Task{await work.send(work.sessionPrompt)}}.buttonStyle(.borderedProminent).disabled(running||work.sessionPrompt.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty)}
 }.frame(minWidth:500)}.task{await work.agents()}.onChange(of:work.selectedSession){_,id in if !id.isEmpty{Task{await work.selectSession(id)}}}
 }
 func operate(_ action:String,extra:[String:Any]=[:]){Task{var input=extra;input["id"]=work.selectedSession;if let r=await work.request(action,input){await work.selectSession(r["id"] as? String ?? "");await work.agents()}}}
}

struct SessionStats:View{
 @EnvironmentObject var work:Workspace
 var body:some View{HStack{FieldView(field:Field("session.inputTokens","Reported input tokens",work.sessionTokens["input_tokens"].map{String($0)} ?? "Unknown",meaning:"Input usage reported by completed CLI turns in this scoped session. This is not an estimate or hosted cash cost."));FieldView(field:Field("session.outputTokens","Reported output tokens",work.sessionTokens["output_tokens"].map{String($0)} ?? "Unknown",meaning:"Output usage reported by completed CLI turns. In-flight or unsupported provider usage remains unknown."));FieldView(field:Field("session.context","Turn",work.sessionInfo["turn"] ?? 0,meaning:"Durable turn number in this CLI session; reset creates new context."));if work.omittedMessages>0{Text("Showing the latest 500 messages; complete history remains local.").font(.caption).foregroundStyle(.secondary)}}}
}
